from typing import List
class Solution:
    def maximumProcessableQueries(self, nums: List[int], queries: List[int]) -> int:
        n, q = len(nums), len(queries)
        dp = [[0] * (n + 1) for _ in range(n + 1)]
        ans = 0
        for s in range(n):
            for f in range(s + 1):
                b = s - f
                cur = dp[f][b]
                if cur >= q:
                    ans = max(ans, cur)
                    continue
                ans = max(ans, cur)
                tq = queries[cur]
                if f < n - b and nums[f] >= tq:
                    dp[f + 1][b] = max(dp[f + 1][b], cur + 1)
                if b < n - f and nums[n - 1 - b] >= tq:
                    dp[f][b + 1] = max(dp[f][b + 1], cur + 1)
        for f in range(n + 1):
            ans = max(ans, dp[f][n - f])
        return ans

