class Solution {
public:
    int maximumProcessableQueries(vector<int>& nums, vector<int>& queries) {
        int n = nums.size(), q = queries.size();
        vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
        int ans = 0;
        for (int s = 0; s < n; s++)
            for (int f = 0; f <= s; f++) {
                int b = s - f, cur = dp[f][b];
                ans = max(ans, cur);
                if (cur >= q) continue;
                int tq = queries[cur];
                if (f < n - b && nums[f] >= tq)
                    dp[f + 1][b] = max(dp[f + 1][b], cur + 1);
                if (b < n - f && nums[n - 1 - b] >= tq)
                    dp[f][b + 1] = max(dp[f][b + 1], cur + 1);
            }
        for (int f = 0; f <= n; f++) ans = max(ans, dp[f][n - f]);
        return ans;
    }
};

