            const tq = queries[cur];
            if (f < n - b && nums[f] >= tq)
                dp[f + 1][b] = Math.max(dp[f + 1][b], cur + 1);
            if (b < n - f && nums[n - 1 - b] >= tq)
                dp[f][b + 1] = Math.max(dp[f][b + 1], cur + 1);
        }
